/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from decimal import Decimal
from zoneinfo import ZoneInfo, available_timezones
from datetime import datetime
import cadence

big = int(Decimal('1' * 5000))
window = ('2025-01-01T00:00Z', '2025-01-02T00:00Z')
valid_rule = {'id': 'r', 'rule': 'every day at 09:00 for 30m from 2025-01-01'}
valid = {'timezone': 'UTC', 'rules': [valid_rule]}
for label, plan in (
    ('plan timezone', {**valid, 'timezone': big}),
    ('rule id', {**valid, 'rules': [{**valid_rule, 'id': big}]}),
    ('rule timezone', {**valid, 'rules': [{**valid_rule, 'timezone': big}]}),
    ('min_segment', {**valid, 'min_segment': [big]}),
    ('override action', {**valid, 'overrides': [{'rule': 'r', 'key': '2025-01-01', 'action': big}]}),
):
    try:
        cadence.occurrences(plan, *window)
    except Exception as exc:
        print(label, '=>', type(exc).__name__, str(exc)[:90])
try:
    cadence.occurrences(valid, big, window[1])
except Exception as exc:
    print('query bound', '=>', type(exc).__name__, str(exc)[:90])
for key in sorted(available_timezones()):
    initial = datetime(1800, 1, 1, tzinfo=ZoneInfo(key))
    offset = initial.utcoffset().total_seconds()
    if -60 < offset < 0:
        print(key, initial.isoformat())
PY"

